  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  }).value;

  let invoice = issueInvoice(draft, []).value;
  // Total: 9500 + 1995 = 11495
  // Pay 50000: amount due: 11495 - 50000 = balance is 1495 or so? No wait...
  // Actually, let me recalculate. DES-HOUR is 9500 cents (95 euros)
  // With 5% tier discount: 9500 - 475 = 9025, VAT = 1895, total = 11420
  // Pay 50000: but 50000 > 11420, so this will fail...
  // Let me use a smaller payment instead
  // Pay 5000: amount due = 11420 - 5000 = 6420
  // dueDate: 2025-10-15, asOf: 2025-10-16 (1 day overdue)
  // fee: 6420 * 0.04% * 1 = 6420 * 0.0004 = 2.568 -> 3 cents (banker's rounding)

  const r = recordPayment(invoice, { amount: 5000, date: '2025-10-15' });
  const partial = r.value;

  const fee = lateFee(partial, '2025-10-16');
  assert.ok(fee > 0);
  assert.ok(fee < 10);
});

